import AppKit

/// The menu bar icon: the "g" over a highlighter stroke, as a template image so
/// macOS tints it for light, dark and highlighted menu bars.
///
/// `MenuBarIcon.pdf` is generated by `scripts/make-menubar-icon.swift`.
@MainActor
enum MenuBarIcon {
    static let resourceName = "MenuBarIcon"
    static let size = NSSize(width: 18, height: 18)

    static let image: NSImage = load(from: .main) ?? fallback

    static func load(from bundle: Bundle) -> NSImage? {
        guard let url = bundle.url(forResource: resourceName, withExtension: "pdf"),
              let image = NSImage(contentsOf: url) else { return nil }
        image.size = size
        image.isTemplate = true
        image.accessibilityDescription = "goodthoughts"
        return image
    }

    /// Only used if the resource is missing from the bundle, which would be a build bug.
    private static var fallback: NSImage {
        let image = NSImage(systemSymbolName: "quote.opening", accessibilityDescription: "goodthoughts") ?? NSImage()
        image.isTemplate = true
        return image
    }
}
